        "code": "# 1. Chay Phoenix R&D Workbench tren 1 container ket noi PostgreSQL noi bo\n# docker run -d --name phoenix-rnd \\\n#   -p 6006:6006 -p 4317:4317 \\\n#   -e PHOENIX_SQL_DATABASE_URL=\"postgresql+psycopg://phoenix:secret@pg-rnd:5432/phoenix_db\" \\\n#   -e PHOENIX_WORKING_DIR=\"/mnt/data\" \\\n#   arizephoenix/phoenix:latest\n\nimport re\nfrom opentelemetry.sdk.trace import SpanProcessor\nfrom phoenix.otel import register\nfrom openinference.instrumentation.openai import OpenAIInstrumentor\nfrom openinference.semconv.trace import SpanAttributes\nfrom opentelemetry import trace\n\nVN_PHONE_RE = re.compile(r\"(?:\\+84|0)(?:3|5|7|8|9)\\d{8}\\b\")\n\n\nclass VnPiiMaskingProcessor(SpanProcessor):\n    \"\"\"Che so dien thoai VN trong thuoc tinh OpenInference truoc khi gui qua OTLP.\"\"\"\n\n    def on_start(self, span, parent_context=None):\n        return None\n\n    def on_end(self, span):\n        if not span.attributes:\n            return\n        for key in (SpanAttributes.INPUT_VALUE, SpanAttributes.OUTPUT_VALUE):\n            val = span.attributes.get(key)\n            if isinstance(val, str):\n                span._attributes[key] = VN_PHONE_RE.sub(\"[MASKED_VN_PHONE]\", val)\n\n\ndef init_internal_phoenix_tracer(project: str = \"domation-rag-staging\"):\n    tracer_provider = register(\n        project_name=project,\n        endpoint=\"http://127.0.0.1:4317\",\n        batch=True,\n        auto_instrument=False,\n    )\n    tracer_provider.add_span_processor(VnPiiMaskingProcessor())\n    OpenAIInstrumentor().instrument(tracer_provider=tracer_provider)\n    return trace.get_tracer(project)\n\n\nif __name__ == \"__main__\":\n    tracer = init_internal_phoenix_tracer()\n    with tracer.start_as_current_span(\"rag.answer_query\") as span:\n        span.set_attribute(SpanAttributes.OPENINFERENCE_SPAN_KIND, \"CHAIN\")\n        span.set_attribute(SpanAttributes.INPUT_VALUE, \"Tu van bang gia EcoLife cho SDT 0912345678\")\n        span.set_attribute(\"rag.kb_namespace\", \"ecolife-danang-q4\")\n        span.set_attribute(SpanAttributes.OUTPUT_VALUE, \"Da truy xuat bang gia can 2PN tang 12.\")"
