        "code": "import json\nimport os\nimport re\nimport pytest\nfrom openai import OpenAI\nfrom deepeval import assert_test\nfrom deepeval.test_case import LLMTestCase\nfrom deepeval.metrics import FaithfulnessMetric, ContextualRecallMetric, DAGMetric\nfrom deepeval.metrics.dag import DeepAcyclicGraph, BinaryJudgementNode, VerdictNode\nfrom deepeval.models.base_model import DeepEvalBaseLLM\n\n\nclass CalibratedLocalJudge(DeepEvalBaseLLM):\n    \"\"\"Adapter tro Judge ve model nhe hoac vLLM noi bo voi temperature=0.\"\"\"\n\n    def __init__(self, model_name: str = \"gemini-2.5-flash\"):\n        self.model_name = model_name\n        self.client = OpenAI(\n            api_key=os.getenv(\"JUDGE_API_KEY\", \"internal-vllm-key\"),\n            base_url=os.getenv(\"JUDGE_BASE_URL\", \"http://localhost:8000/v1\"),\n        )\n\n    def load_model(self):\n        return self.client\n\n    def generate(self, prompt: str, schema=None) -> str:\n        resp = self.client.chat.completions.create(\n            model=self.model_name,\n            temperature=0.0,\n            messages=[{\"role\": \"user\", \"content\": prompt}],\n        )\n        return resp.choices[0].message.content or \"\"\n\n    async def a_generate(self, prompt: str, schema=None) -> str:\n        return self.generate(prompt, schema=schema)\n\n    def get_model_name(self) -> str:\n        return f\"calibrated-{self.model_name}\"\n\n\ndef deterministic_precheck(raw_json_output: str, required_sku: str) -> dict:\n    \"\"\"Tang 1: Assert code cung chi phi 0 dong truoc khi goi LLM Judge.\"\"\"\n    payload = json.loads(raw_json_output)\n    assert \"answer\" in payload and len(payload[\"answer\"].strip()) >= 20, \"Cau tra loi qua ngan\"\n    assert payload.get(\"sku\") == required_sku, f\"Lech ma SKU: {payload.get('sku')}\"\n    assert not re.search(r\"\\bmiễn phí 100%\\b\", payload[\"answer\"], re.IGNORECASE), (\n        \"Vi pham quy tac cam ket gia cam trong tai lieu noi bo\"\n    )\n    return payload\n\n\njudge_llm = CalibratedLocalJudge()\n\ncompliance_dag = DeepAcyclicGraph(\n    nodes=[\n        BinaryJudgementNode(\n            criteria=\"Phan hoi co neu dung yeu cau do phan giai 300 DPI khi xuat file in khong?\",\n            children=[\n                VerdictNode(verdict=True, score=1.0),\n                VerdictNode(verdict=False, score=0.0),\n            ],\n        )\n    ]\n)\n\n\n@pytest.mark.parametrize(\n    \"user_query,raw_output,expected_output,contexts,sku\",\n    [\n        (\n            \"Chuan file AOP 3D ma AOP-208 can xuat bao nhieu DPI va lech pixel toi da?\",\n            json.dumps({\n                \"sku\": \"AOP-208\",\n                \"answer\": \"Ma AOP-208 yeu cau Neural Extract dat chuan 300 DPI voi sai so khop rap 0 pixel.\",\n            }),\n            \"Tieu chuan AOP-208 la 300 DPI va 0 pixel lech.\",\n            [\"Quy chuan INKICA 208 SKU: Neural Extract 300 DPI tach lop, boc rap .PSD CAD dat 0 pixel lech.\"],\n            \"AOP-208\",\n        )\n    ],\n)\ndef test_rag_and_prepress_quality_gate(user_query, raw_output, expected_output, contexts, sku):\n    # Tang 1: Neu fail o day se dung ngay, khong ton tien LLM Judge\n    parsed = deterministic_precheck(raw_output, sku)\n\n    # Tang 2 & 3: Chi chay khi da vuot qua hop dong du lieu cung\n    test_case = LLMTestCase(\n        input=user_query,\n        actual_output=parsed[\"answer\"],\n        expected_output=expected_output,\n        retrieval_context=contexts,\n    )\n    metrics = [\n        DAGMetric(name=\"Prepress Spec Rule\", dag=compliance_dag, threshold=0.9, model=judge_llm),\n        FaithfulnessMetric(threshold=0.85, model=judge_llm, include_reason=True),\n        ContextualRecallMetric(threshold=0.80, model=judge_llm),\n    ]\n    assert_test(test_case, metrics)"
