        "code": "-- PHAN 1: PostgreSQL Migration — Co lap tuyet doi Du lieu Lead & Vector RAG\nCREATE EXTENSION IF NOT EXISTS vector;\n\nCREATE TABLE crm_leads (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id uuid NOT NULL,\n  phone_normalized varchar(20) NOT NULL,\n  stage varchar(32) NOT NULL DEFAULT 'new_lead',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE rag_knowledge_chunks (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id uuid NOT NULL,\n  doc_title text NOT NULL,\n  content text NOT NULL,\n  embedding vector(1536) NOT NULL\n);\n\nCREATE INDEX idx_crm_leads_tenant_phone ON crm_leads (tenant_id, phone_normalized);\nCREATE INDEX idx_rag_chunks_hnsw ON rag_knowledge_chunks USING hnsw (embedding vector_cosine_ops);\n\n-- Bat va EP BUOC RLS ap dung cho ca Table Owner\nALTER TABLE crm_leads ENABLE ROW LEVEL SECURITY;\nALTER TABLE crm_leads FORCE ROW LEVEL SECURITY;\n\nALTER TABLE rag_knowledge_chunks ENABLE ROW LEVEL SECURITY;\nALTER TABLE rag_knowledge_chunks FORCE ROW LEVEL SECURITY;\n\nCREATE POLICY tenant_isolation_leads ON crm_leads\n  USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)\n  WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);\n\nCREATE POLICY tenant_isolation_rag ON rag_knowledge_chunks\n  USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid)\n  WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);\n\n-- PHAN 2: TypeScript Backend Wrapper (Fastify / Next.js) an toan voi Supavisor Pooler\n/*\nexport async function withTenantTx<T>(pool: Pool, tenantId: string, fn: (client: PoolClient) => Promise<T>) {\n  const client = await pool.connect();\n  try {\n    await client.query('BEGIN');\n    // SET LOCAL chi co hieu luc trong transaction nay, tu reset khi tra connection ve pool\n    await client.query(\"SELECT set_config('app.current_tenant_id', $1, true)\", [tenantId]);\n    const result = await fn(client);\n    await client.query('COMMIT');\n    return result;\n  } catch (err) {\n    await client.query('ROLLBACK');\n    throw err;\n  } finally {\n    client.release();\n  }\n}\n*/"
